def compute_color_bbox_and_mirror(grid, color):
    """Compute bbox for color, extract pattern, return mirrored extension"""
    pixels = []
    min_r, max_r, min_c, max_c = 999, 0, 999, 0

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                pixels.append((r, c))
                min_r, max_r = min(min_r, r), max(max_r, r)
                min_c, max_c = min(min_c, c), max(max_c, c)

    if not pixels:
        return None

    bbox_h = max_r - min_r + 1
    # Pattern within bbox
    pattern = {}
    for r_rel in range(bbox_h):
        pattern[r_rel] = set()
        for c_rel in range(max_c - min_c + 1):
            abs_r, abs_c = min_r + r_rel, min_c + c_rel
            if abs_r < len(grid) and grid[abs_r][abs_c] == color:
                pattern[r_rel].add(c_rel)

    return {
        'min_r': min_r, 'max_r': max_r,
        'min_c': min_c, 'max_c': max_c,
        'bbox_h': bbox_h,
        'pattern': pattern
    }

def mirror_extension(grid, color_data):
    """Create extended grid with vertical mirror of the bbox"""
    result = [[0]*len(grid[0]) for _ in range(len(grid))]

    # Copy original color pixels
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                result[r][c] = color

    # Add mirrored rows below
    max_r = color_data['max_r']
    bbox_h = color_data['bbox_h']

    # Mirror starts immediately after max_r
    for out_r in range(max_r + 1, len(grid)):
        # Source row in original bbox (mirrored)
        dist = out_r - max_r
        if dist < bbox_h:
            src_r = bbox_h - 1 - dist
        else:
            cycle = 2 * bbox_h
            cycle_idx = dist % cycle
            if cycle_idx < bbox_h:
                src_r = cycle_idx
            else:
                src_r = bbox_h - 1 - (cycle_idx - bbox_h)

        # Fill pixels from source row
        for rel_c in color_data['pattern'][src_r]:
            abs_c = color_data['min_c'] + rel_c
            result[out_r][abs_c] = color

    return result

