def get_bbox_pattern(grid, color):
    min_r, max_r, min_c, max_c = 999, 0, 999, 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                min_r, max_r = min(min_r, r), max(max_r, r)
                min_c, max_c = min(min_c, c), max(max_c, c)

    bbox_h = max_r - min_r + 1
    pattern = {}
    for r_rel in range(bbox_h):
        pattern[r_rel] = set(c - min_c for c in range(min_c, max_c + 1) 
                            if grid[min_r + r_rel][c] == color)

    return {'min_r': min_r, 'max_r': max_r, 'min_c': min_c, 'bbox_h': bbox_h, 'pattern': pattern}

def circular_repeat_extend(grid, bbox_data):
    result = [[0]*len(grid[0]) for _ in range(len(grid))]

    # Copy original color pixels
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == bbox_data['color']:
                result[r][c] = bbox_data['color']

    # Add circular repeat rows below
    max_r = bbox_data['max_r']
    bbox_h = bbox_data['bbox_h']

    for out_r in range(max_r + 1, len(grid)):
        # Circular index
        src_r = (out_r - (min(bbox_data['min_r'], max_r))) % bbox_h

        for rel_c in bbox_data['pattern'][src_r]:
            abs_c = bbox_data['min_c'] + rel_c
            result[out_r][abs_c] = bbox_data['color']

    return result

