            if val != 0:
                result[r][c] = val

    # Then expand each color that spans multiple rows
    # Only expand colors where bbox height > 1
    from collections import defaultdict
    color_bboxes = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                color_bboxes[grid[r][c]].append((r,c))

    for color, pixels in color_bboxes.items():
        min_r, max_r = min(p[0] for p in pixels), max(p[0] for p in pixels)
        min_c, max_c = min(p[1] for p in pixels), max(p[1] for p in pixels)

        bbox_h = max_r - min_r + 1

        if bbox_h == 1:
            # Single row - no vertical expansion needed
            continue

        # Build pattern
        pattern = {}
        for r_rel in range(bbox_h):
            pattern[r_rel] = set(c - min_c for c in range(min_c, max_c + 1) 
                                if grid[min_r + r_rel][c] == color)

        # Add mirrored rows below
        for out_r in range(max_r + 1, len(grid)):
            dist = out_r - max_r
            if dist < bbox_h:
                src_r = bbox_h - 1 - dist
            else:
                cycle = 2 * bbox_h
                cycle_idx = dist % cycle
                if cycle_idx < bbox_h:
                    src_r = cycle_idx
                else:
                    src_r = bbox_h - 1 - (cycle_idx - bbox_h)

            for rel_c in pattern[src_r]:
                abs_c = min_c + rel_c
                if grid[out_r][abs_c] == 0:  # Don't overwrite existing pixels
                    result[out_r][abs_c] = color

    return result

